package compile

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"

	"git.phin.tech/sam/starci/internal/plan"
)

func compileCircle(t *testing.T, src string, o Options) string {
	t.Helper()
	p, read, err := plan.EvalTracked("ci.star", []byte(src), plan.Context{})
	if err != nil {
		t.Fatal(err)
	}
	o.Read = read
	out, err := CircleCI(p, o)
	if err != nil {
		t.Fatal(err)
	}
	return out
}

func TestCircleCIStepsBecomeJobs(t *testing.T) {
	out := compileCircle(t, script, Options{Source: "ci.star"})
	wants(t, out,
		"# Generated by `starci compile --target circleci` from ci.star.",
		"version: 2.1\n",
		// The job starts the step's container itself, which needs a machine.
		"  lint:\n    machine:\n      image: ubuntu-2404:current\n    resource_class: medium\n    steps:\n      - checkout\n",
		"git sparse-checkout set --no-cone '/app/**/*.py' '/pyproject.toml'",
		"curl -fsSL 'https://example.com/uv-x86_64.tar.gz' -o /tmp/uv.download",
		`echo "`+sum+`  /tmp/uv.download" | sha256sum -c -`,
		`-e "PATH=/opt/starci/tools/uv/uv-x86_64:$image_path"`,
		"starci-env-api-tests sh -c \"$STARCI_RUN\"",
		"            STARCI_RUN: |-\n              uv run pytest -q && echo 'it''s done'\n",
		// Dependencies are the workflow's, not the job's.
		"workflows:\n  ci:\n    jobs:\n      - lint\n      - api-tests:\n          requires: [lint]\n",
	)
}

func TestCircleCIStartsASealedStepWithoutTheNetwork(t *testing.T) {
	if out := compileCircle(t, script, Options{}); strings.Contains(out, "--network") {
		t.Errorf("a step with the network was started without it:\n%s", out)
	}
	sealed := compileCircle(t, strings.Replace(script, `ruff check app",`, `ruff check app", network = False,`, 1), Options{})
	wants(t, sealed, "  --network none \\\n")
}

func TestCircleCIKeysAPassOnTheExactInputs(t *testing.T) {
	out := compileCircle(t, script, Options{})
	wants(t, out,
		// The files are asked of git with the pathspecs a worker uses...
		"git ls-files -s -- ':(top,glob)app/**/*.py' ':(top,literal)pyproject.toml' > /tmp/starci-inputs",
		"git ls-files -s -- ':(top,literal)app' ':(top,literal)tests' > /tmp/starci-inputs",
		// ...and their listing is what the record of a pass is keyed on.
		`-{{ checksum "/tmp/starci-inputs" }}`,
		"if [ -e ~/starci-passed/at ]; then",
		"circleci-agent step halt",
		"          paths:\n            - ~/starci-passed\n",
	)
	// The pass is restored and saved under the same key.
	i := strings.Index(out, "starci-passed-lint-")
	key := out[i : strings.Index(out[i:], "\n")+i]
	if strings.Count(out, key) != 2 {
		t.Errorf("the key %q appears %d times, want once to restore and once to save", key, strings.Count(out, key))
	}
}

// "<<" starts a parameter in a CircleCI configuration, wherever it appears.
func TestCircleCIEscapesItsOwnTemplating(t *testing.T) {
	out := compileCircle(t, `
def ci(ctx):
    return [step("heredoc", image = "debian:12-slim", packages = ["jq"], run = "cat <<EOF\nhello\nEOF")]
`, Options{})
	wants(t, out,
		`docker build -q -t starci-env-heredoc - \<<'DOCKERFILE'`,
		"              cat \\<<EOF\n              hello\n              EOF\n",
	)
	if strings.Contains(strings.ReplaceAll(out, `\<<`, ""), "<<") {
		t.Errorf("an unescaped << is left in the configuration:\n%s", out)
	}
}

func TestCircleCISaysWhatItDrops(t *testing.T) {
	out := compileCircle(t, `
def ci(ctx):
    if ctx.changed_files:
        return []
    return [step("gpu", image = "alpine:3", run = "true", worker = {"gpu": "true"})]
`, Options{})
	wants(t, out,
		"The script reads ctx.changed_files, so its plan depends on the commit.",
		// The note is wrapped into the header, so only a stretch of it is looked for.
		"`worker`, `prefer` and `avoid` have no equivalent here",
		"(gpu)",
		"    resource_class: medium\n",
	)
	if arm := compileCircle(t, "def ci(ctx):\n    return [step(\"a\", image = \"alpine:3\", run = \"true\")]\n", Options{Arch: "arm64"}); !strings.Contains(arm, "resource_class: arm.medium") {
		t.Errorf("an arm64 build did not ask for an arm machine:\n%s", arm)
	}
}

// Every basic example compiles, and where CircleCI's own tool is installed,
// what it compiles to is a configuration that tool accepts.
func TestExamplesCompileForCircleCI(t *testing.T) {
	files, _ := filepath.Glob(filepath.Join("..", "..", "examples", "basic", "*.star"))
	if len(files) == 0 {
		t.Fatal("no examples found")
	}
	cli, _ := exec.LookPath("circleci")
	for _, file := range files {
		t.Run(filepath.Base(file), func(t *testing.T) {
			src, err := os.ReadFile(file)
			if err != nil {
				t.Fatal(err)
			}
			p, read, err := plan.EvalTracked(file, src, plan.Context{})
			if err != nil {
				t.Fatal(err)
			}
			out, err := CircleCI(p, Options{Source: filepath.Base(file), Read: read})
			if err != nil {
				t.Fatal(err)
			}
			// The validator asks CircleCI's servers.
			if cli == "" || testing.Short() {
				return
			}
			path := filepath.Join(t.TempDir(), "config.yml")
			os.WriteFile(path, []byte(out), 0o644)
			if msg, err := exec.Command(cli, "config", "validate", "--skip-update-check", path).CombinedOutput(); err != nil {
				t.Errorf("circleci rejects the configuration:\n%s", msg)
			}
		})
	}
}

func TestCircleCIStartsAJobsServicesAndStopsThem(t *testing.T) {
	out := compileCircle(t, withServices, Options{})
	wants(t, out,
		"      - run:\n          name: \"Services: postgres, store\"\n",
		`            docker network create "starci-$CIRCLE_BUILD_NUM-api-tests"`+"\n",
		`--network-alias postgres --hostname postgres -e 'POSTGRES_PASSWORD=it'\''s' postgres:17`+"\n",
		`            until timeout 10 docker exec "starci-$CIRCLE_BUILD_NUM-api-tests-postgres" sh -c 'pg_isready -h localhost'; do`+"\n",
		`  --network "starci-$CIRCLE_BUILD_NUM-api-tests" \`+"\n",
		"      - run:\n          name: Stop the services\n          when: always\n",
		`            docker network rm "starci-$CIRCLE_BUILD_NUM-api-tests" || true`+"\n",
	)
}
